(()=>{const header=document.querySelector('header'),toggle=document.querySelector('.menu-toggle'),menu=document.querySelector('#main-menu');if(!header||!toggle||!menu)return;header.classList.add('js-menu');const close=()=>{toggle.setAttribute('aria-expanded','false');menu.classList.remove('is-open')};toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));menu.classList.toggle('is-open',open)});menu.addEventListener('click',event=>{if(event.target.closest('a'))close()});header.addEventListener('keydown',event=>{if(event.key==='Escape'){close();toggle.focus()}})})();
// The visit section already includes a booking button; keep its hours unobstructed.
(()=>{const section=document.querySelector('#localizacao');if(section&&'IntersectionObserver' in window)new IntersectionObserver(([entry])=>document.body.classList.toggle('in-visit',entry.isIntersecting)).observe(section)})();
